const locationLabel=entity=>entityLocations(entity).map(x=>x.label).join(', ')||entity?.city||'Helyszín nincs megadva';
const rangeLabel=(min,max,unit='')=>{const has=v=>v!==null&&v!==undefined&&v!=='';return has(min)&&has(max)?`${num(min)}–${num(max)} ${unit}`.trim():has(min)?`legalább ${num(min)} ${unit}`.trim():has(max)?`legfeljebb ${num(max)} ${unit}`.trim():'Nincs megkötés';};
