const floorLabel=(value,bucket=false)=>!hasAttribute(value)?'Nincs megadva':bucket?(FLOOR_OPTIONS.find(option=>option.value===Number(value))?.label||`${num(value)}. emelet`):Number(value)===-1?'Szuterén':Number(value)===0?'Földszint':Number(value)===11?'11 vagy afölötti':Number(value)<0?`${num(value)}. szint`:`${num(value)}. emelet`;
