const isSeller=()=>state?.active?.kind==='property';
const currentLikeCost=()=>likeCost(state?.user?.accountType,state?.active?.kind);
const likeLabel=()=>isSeller()?'Ajánlom · 2 kredit':currentLikeCost()?'Tetszik · 1 kredit':'Tetszik';
const likeActionLabel=()=>isSeller()?'Ingatlan ajánlása, 2 kredit':currentLikeCost()?'Tetszik az ingatlan, 1 kredit':'Tetszik az ingatlan';
function accountTypeSelect(id='f-accountType'){return `<div class="field"><label for="${id}">Milyen minőségben regisztrálsz?</label><select id="${id}" name="accountType" required>${ACCOUNT_TYPE_OPTIONS.map(option=>`<option value="${option.value}">${esc(option.label)}</option>`).join('')}</select></div>`;}
function agentBadge(entity){if(entity?.ownerId&&entity.ownerId===state?.user?.id)return '';const agent=normalizeAccountType(entity?.ownerAccountType)==='agent';return `<span class="account-badge ${agent?'agent-badge':'private-badge'}">${icon(agent?'building':'home')}${agent?'Ingatlanközvetítő':'Magánszemély'}</span>`;}
function ownerInfo(entity){if(entity?.ownerId&&entity.ownerId===state?.user?.id)return '';const name=String(entity?.ownerFirstName||'').trim();return name?`<span class="owner-info"><span class="owner-initial" aria-hidden="true">${esc(initials(name))}</span><span class="owner-first-name">${esc(name)}</span></span>`:'';}
function partnerBadge(partner){return agentBadge({ownerId:partner?.id,ownerAccountType:partner?.accountType});}
function reportControl(entity,kind){if(!entity?.ownerId||!entity?.id||entity.ownerId===state?.user?.id||entity.archived)return '';return `<div class="report-tools"><button type="button" class="report-button" data-action="report-account" data-kind="${esc(kind)}" data-id="${esc(entity.id)}">${icon('info')}Hirdetés jelentése</button></div>`;}
function reportEntity(kind,id){const candidates=[...feed.filter(entity=>entity.kind===kind),...incoming.filter(entity=>entity.kind===kind),...(kind==='property'?state?.properties||[]:state?.searches||[]),...(state?.decisions||[]).map(decision=>kind==='property'?decision.property:decision.search),...matches.map(match=>kind==='property'?match.property:match.search)];return candidates.find(entity=>entity?.id===id&&entity.ownerId!==state?.user?.id);}
function openReport(kind,id){const entity=reportEntity(kind,id);if(!['property','search'].includes(kind)||!entity||!reportControl(entity,kind))return;const options=getReportReasons(entity.ownerAccountType),reported=(state.reportedEntities||[]).filter(report=>report.entityKind===kind&&report.entityId===id);openModal(`<div class="eyebrow">Hirdetés jelentése</div><h2>Hirdetés jelentése</h2><p class="modal-description">A(z) <strong>${esc(entity.title)}</strong> profilnál válaszd ki, milyen szabálytalanságot tapasztaltál.</p><div class="field"><label for="f-reportReason">Jelentés oka</label><select id="f-reportReason" name="reportReason" required><option value="" selected>Válassz egy okot</option>${options.map(option=>`<option value="${esc(option.value)}">${esc(option.label)}</option>`).join('')}</select></div>${reported.length?`<p class="detail-copy report-history">Korábban jelzett ok: ${reported.map(report=>esc(REPORT_REASON_OPTIONS.find(option=>option.value===report.reason)?.label||report.reason)).join(', ')}.</p>`:''}<div class="modal-actions report-actions"><button class="btn btn-outline" data-action="close">Mégse</button><button class="btn btn-orange" data-action="confirm-report" data-kind="${esc(kind)}" data-id="${esc(id)}">Jelentés elküldése</button></div>`);}
function openCreditsNeeded(){const cost=currentLikeCost();openModal(`<h2>Kreditekre van szükséged.</h2><p class="modal-description">${isSeller()?'Az ingatlanajánláshoz':'Ingatlanközvetítőként ehhez a kedveléshez'} ${cost} kredit szükséges. A jelenlegi egyenleged ${num(state.credits)} kredit.</p><div class="modal-actions"><button class="btn btn-outline" data-action="close">Mégse</button><button class="btn btn-orange" data-page="credits">Kreditek feltöltése</button></div>`);}

let toastTimer,modalCleanup;
function toast(message,error=false){const el=document.getElementById('toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4200);}
async function run(fn){if(busy)return;busy=true;try{await fn();}catch(e){if(hosted&&e.status===401){await expireSession(e.message);}else toast(e.message||'A művelet nem sikerült.',true);}finally{busy=false;}}
async function expireSession(message){resetRecommendations();closeModal();model=disconnectApi();initError=null;state=null;feed=[];matches=[];incoming=[];incomingPage=null;notificationPage=null;authMode='login';location.hash='login';authMessage=message||'A munkameneted lejárt. Jelentkezz be újra.';await render();}
